// Spring Boot ya valida la pregunta; aquí se vuelve a validar porque el flujo no debe confiar en nadie
const b = $input.first().json.body || {};
const pregunta = String(b.pregunta ?? '').trim();
if (pregunta.length < 3 || pregunta.length > 500) {
  throw new Error('La pregunta debe tener entre 3 y 500 caracteres');
}
const umbral = Number(b.umbral);
if (!(umbral > 0 && umbral < 1)) {
  throw new Error('El umbral debe estar entre 0 y 1');
}
const maxFuentes = Math.min(Math.max(parseInt(b.max_fuentes ?? 5, 10) || 5, 1), 5);
return [{ json: { consulta_id: b.consulta_id ?? null, pregunta, umbral, max_fuentes: maxFuentes } }];

// Candidatos de pgvector ordenados por similitud (ya solo negocios activos). Se quedan los que superan el umbral.
const entrada = $('Validar entrada').first().json;
const candidatos = $input.all()
  .map((i) => i.json)
  .filter((c) => c.establecimiento_id != null)
  .map((c) => ({ establecimiento_id: Number(c.establecimiento_id), nombre: c.nombre, similitud: Number(c.similitud) }));
const fuentes = candidatos.filter((c) => c.similitud >= entrada.umbral);
return [{
  json: {
    fuentes,
    candidatos,
    mejor_similitud: candidatos.length ? candidatos[0].similitud : null,
    umbral: entrada.umbral,
  },
}];

const f = $input.first().json;
return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'Ningún negocio supera el umbral de similitud',
                  mejor_similitud: f.mejor_similitud, umbral: f.umbral, candidatos: f.candidatos } }];

// Solo las fichas que FastAPI devolvió (si un negocio se desactivó entre la búsqueda y este paso, ya no viene)
const fichas = $input.first().json.fichas || [];
const recuperadas = $('Filtrar por umbral').first().json.fuentes;
const ids = new Set(fichas.map((f) => f.id));
const fuentes = recuperadas.filter((f) => ids.has(f.establecimiento_id));
const pregunta = $('Validar entrada').first().json.pregunta;
const cuerpo = {
  systemInstruction: { parts: [{ text: "Eres el asistente de Easy Search, una plataforma para encontrar negocios, productos y servicios en Bucaramanga y su área metropolitana (Colombia).
Recibirás la pregunta de un usuario y las FICHAS de los negocios que la búsqueda semántica encontró como más relacionados.

Reglas OBLIGATORIAS:
- Las fichas vienen de una búsqueda por similitud y pueden incluir negocios que NO sirven para lo que el usuario pide (ej. un bar o un supermercado cuando pide una farmacia). Descarta esas fichas: no las menciones ni las incluyas en fuentes_usadas. Solo cuenta un negocio si su ficha muestra que ofrece lo que se pide.
- UBICACIÓN: la ubicación de cada negocio es SOLO la del campo "ubicacion" de su ficha. Nunca digas que un negocio está en el barrio o municipio que pidió el usuario si su ficha dice otro. Si el usuario pidió una zona y el negocio está en otra, dilo claramente (ej. "no encontré opciones en Cabecera; la más cercana registrada está en Piedecuesta").
- Si después de descartar no queda ningún negocio que sirva, responde tiene_respuesta = false aunque haya fichas.
- Usa EXCLUSIVAMENTE la información de las fichas. No inventes negocios, productos, precios, horarios, direcciones, teléfonos, reseñas ni calificaciones.
- NO deduzcas servicios ni especialidades a partir del NOMBRE de un negocio: usa solo los campos de su ficha.
- Si las fichas NO permiten responder la pregunta (por ejemplo pide una receta, información general, tareas, noticias, o algo que ninguno de esos negocios ofrece), responde tiene_respuesta = false, deja pasos y fuentes_usadas vacíos y en respuesta explica en una frase que no hay información suficiente en Easy Search.
- Si sí se puede responder: tiene_respuesta = true; respuesta = 2 a 4 frases en español, en segunda persona, orientando al usuario entre las opciones y nombrando los negocios; pasos = 2 a 4 pasos concretos y accionables basados en las fichas (por ejemplo qué negocio revisar primero y por qué, qué producto preguntar, confirmar el precio o el horario directamente con el negocio); fuentes_usadas = ids de las fichas en las que te basaste.
- Si una ficha tiene poca información, dilo con honestidad en lugar de rellenar.
- Nombra los negocios solo por su nombre (y su barrio o municipio si ayuda a distinguirlos). NUNCA menciones ids, números de ficha ni la palabra "ficha": el usuario no los conoce.
- Tono amable y directo. Sin listas dentro de "respuesta"." }] },
  contents: [{ role: 'user', parts: [{ text: JSON.stringify({ pregunta, fichas }) }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema: {"type": "object", "properties": {"tiene_respuesta": {"type": "boolean"}, "respuesta": {"type": "string"}, "pasos": {"type": "array", "items": {"type": "string"}}, "fuentes_usadas": {"type": "array", "items": {"type": "integer"}}}, "required": ["tiene_respuesta", "respuesta", "pasos", "fuentes_usadas"]}, temperature: 0.2 },
};
return [{ json: { fuentes, cuerpo: JSON.stringify(cuerpo) } }];

// Respuesta de Gemini (modelo principal o de respaldo, el que haya respondido)
const data = $input.first().json;
let r;
try {
  r = JSON.parse(data.candidates[0].content.parts[0].text);
} catch (e) {
  throw new Error('Gemini devolvió una respuesta que no es JSON válido');
}
const fuentes = $('Armar prompt').first().json.fuentes;
const recuperados = new Set(fuentes.map((f) => f.establecimiento_id));
// Solo cuentan como fuentes los ids que la búsqueda recuperó: si Gemini cita otro id, se descarta
const usadas = (r.fuentes_usadas || []).map(Number).filter((id) => recuperados.has(id));
return [{
  json: {
    tiene_respuesta: r.tiene_respuesta === true && usadas.length > 0,
    respuesta: String(r.respuesta || '').trim(),
    pasos: (r.pasos || []).map((p) => String(p).trim()).filter(Boolean).slice(0, 6),
    ids: usadas,
    modelo: data.modelVersion || $env.GEMINI_MODEL,
  },
}];

const f = $('Filtrar por umbral').first().json;
return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'Las fuentes encontradas no responden la pregunta',
                  explicacion: $input.first().json.respuesta, mejor_similitud: f.mejor_similitud, umbral: f.umbral } }];

// Resultado final para Spring Boot
const validado = $input.first().json;               // respuesta y pasos ya sin datos inventados
const gemini = $('Leer respuesta de Gemini').first().json;
const filtro = $('Filtrar por umbral').first().json;
const porId = new Map($('Armar prompt').first().json.fuentes.map((f) => [f.establecimiento_id, f]));
const fuentes = gemini.ids.map((id) => porId.get(id)).filter(Boolean);
if ((validado.respuesta || '').length < 15) {
  // La validación eliminó casi todo: era información sin respaldo en las fichas
  return [{ json: { estado: 'SIN_RESULTADOS', motivo: 'La respuesta generada no tenía respaldo en los datos',
                    mejor_similitud: filtro.mejor_similitud, umbral: filtro.umbral } }];
}
return [{
  json: {
    estado: 'RESPONDIDA',
    respuesta: validado.respuesta,
    pasos: validado.pasos,
    fuentes,
    mejor_similitud: filtro.mejor_similitud,
    umbral: filtro.umbral,
    modelo: gemini.modelo,
    frases_eliminadas: validado.frases_eliminadas === true,
  },
}];

// Llega aquí cuando falla un paso (salida de error de los nodos HTTP y Postgres)
const mensajes = {
  'Vector de la pregunta (e5)': 'El servicio de embeddings no respondió',
  'Buscar en pgvector': 'La búsqueda en pgvector falló',
  'Fichas de las fuentes': 'No se pudieron leer las fichas de los negocios',
  'Gemini (respaldo)': 'Gemini no respondió (modelo principal y de respaldo)',
  'Validar contra las fichas': 'No se pudo validar la respuesta contra los datos',
};
const paso = $prevNode.name;
const tecnico = String($input.first().json.error?.message || $input.first().json.error || '').slice(0, 200);
return [{ json: { estado: 'ERROR', detalle: mensajes[paso] || `Falló el paso ${paso}`, paso, tecnico } }];
